package com.warehouse.web; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class ApiErrors{@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<?> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}@ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> missing(RuntimeException e){return ResponseEntity.status(404).body(Map.of("error",e.getMessage()));}}
